// Build src/site-keywords.json — the site's search/AI keyword set.
//
// Combines:
//   1. Anchor phrases from src/channel-config.json (brand + Nepal geo terms)
//   2. Tags and frequent topics from the latest YouTube video descriptions
//      (the SEO window — see SEO_VIDEO_COUNT in update-channel-videos.mjs)
//
// Consumers: index.html meta keywords, the Seo component, llms.txt, and the RSS
// feed. Regenerated by the daily workflow, so keywords follow real video topics.

import {readFile, writeFile} from 'node:fs/promises';

const config = await readFile(new URL('../src/channel-config.json', import.meta.url), 'utf8').then(JSON.parse).catch(() => ({}));
const videos = JSON.parse(await readFile(new URL('../src/channel-videos.json', import.meta.url), 'utf8'));
const SEO_VIDEO_COUNT = Number(process.env.SEO_VIDEO_COUNT) || 17;

const STOPWORDS = new Set(('a,an,the,and,or,but,if,then,else,when,at,by,for,with,about,against,between,into,through,during,before,after,above,below,to,from,up,down,in,out,on,off,over,under,again,further,once,here,there,all,any,both,each,few,more,most,other,some,such,no,nor,not,only,own,same,so,than,too,very,can,will,just,should,now,is,am,are,was,were,be,been,being,have,has,had,having,do,does,did,doing,would,could,shall,may,might,must,of,it,its,this,that,these,those,i,you,he,she,we,they,them,his,her,their,our,your,my,me,him,us,what,which,who,whom,as,because,while,where,how,also,get,like,one,two,new,first,last,way,even,still,really,much,many,well,back,go,going,make,made,take,took,see,know,think,say,said,come,came,want,use,used,find,found,give,tell,work,call,try,ask,need,feel,become,leave,put,mean,keep,let,begin,seem,help,show,hear,play,run,move,live,believe,hold,bring,happen,write,provide,sit,stand,lose,pay,meet,include,continue,set,learn,change,lead,understand,watch,follow,stop,create,speak,read,allow,add,spend,grow,open,walk,win,offer,remember,love,consider,appear,buy,wait,serve,send,expect,build,stay,fall,cut,reach,remain,suggest,raise,pass,sell,require,report,decide,pull,return,explain,hope,develop,carry,break,receive,agree,support,hit,produce,eat,cover,catch,draw,choose,cause,point,listen,realize,place,close,involve,increase,reduce,establish,join,unit,plan,state,okay,yeah,yes,hi,hello,hey,thanks,thank,please,welcome,sorry,today,tomorrow,yesterday,ever,never,always,sometimes,often,usually,already,yet,almost,enough,quite,rather,kind,sort,lot,lots,ton,tons,bit,little,big,huge,small,large,great,good,bad,best,better,worse,worst,high,low,long,short,old,young,right,left,true,false,real,same,different,important,special,free,full,half,next,previous,early,late,quick,slow,hard,easy,simple,complex,clear,sure,certain,possible,impossible,available,ready,able,unable,afraid,angry,happy,sad,tired,excited,bored,surprised,interested,interesting,amazing,awesome,cool,nice,fine,super,such,whatever,whichever,whoever,whichever,wherever,whenever,however,despite,except,besides,including,regarding,concerning,according,thanks,due,owing,regardless,per,via,versus,etc,eg,ie,your,yours,mine,ours,theirs,itself,themselves,himself,herself,myself,ourselves,yourself,yourselves,does,done,went,gone,came,seen,taken,made,known,shown,written,been,being,having,doing,said,told,given,taken,left,kept,held,brought,thought,bought,fought,sought,taught,caught,bought,found,bound,ground,sound,round,around,about,above,across,after,against,along,among,around,before,behind,beneath,beside,beyond,despite,except,inside,outside,throughout,toward,towards,underneath,unlike,until,upon,within,without').split(','));

const candidates = new Map();
const addCandidate = (phrase, weight = 1) => {
  const cleaned = String(phrase || '').toLowerCase().trim().replace(/\s+/g, ' ').replace(/["'“”‘’()[\]{}|\\/<>,.;:!?…–—-]+$/g, '').replace(/^["'“”‘’()[\]{}|\\/<>,.;:!?…–—-]+/g, '').trim();
  if (cleaned.length < 3 || cleaned.length > 60) return;
  if (STOPWORDS.has(cleaned)) return;
  candidates.set(cleaned, (candidates.get(cleaned) || 0) + weight);
};

// Anchor phrases always lead the list.
for (const anchor of config.seoAnchors || []) addCandidate(anchor, 100);

// Tags from the latest videos carry the most signal.
const seoVideos = videos.slice(0, SEO_VIDEO_COUNT);
for (const video of seoVideos) {
  for (const tag of video.tags || []) addCandidate(tag, 5);
}

// Frequent unigrams and bigrams from titles + descriptions of the SEO window.
const text = seoVideos.map(video => `${video.title} ${video.description || video.summary || ''}`).join(' \n ');
const words = text.toLowerCase().replace(/https?:\/\/\S+/g, ' ').replace(/[^a-z0-9\s]/g, ' ').split(/\s+/).filter(Boolean);
for (let i = 0; i < words.length; i++) {
  const word = words[i];
  if (word.length > 3 && !STOPWORDS.has(word) && !/^\d+$/.test(word)) addCandidate(word, 1);
  if (i + 1 < words.length) {
    const next = words[i + 1];
    if (word.length > 2 && next.length > 2 && !STOPWORDS.has(word) && !STOPWORDS.has(next)) addCandidate(`${word} ${next}`, 1);
  }
}

// Nepal-adjacent compound topics get a boost so geo searches rank.
for (const keyword of [...candidates.keys()]) {
  if (/\bnepal/.test(keyword)) candidates.set(keyword, candidates.get(keyword) + 4);
  if (/podcast/.test(keyword)) candidates.set(keyword, candidates.get(keyword) + 2);
}

const keywords = [...candidates.entries()].sort((a, b) => b[1] - a[1]).slice(0, 60).map(([keyword]) => keyword);
await writeFile(new URL('../src/site-keywords.json', import.meta.url), `${JSON.stringify(keywords, null, 2)}\n`);
console.log(`Wrote ${keywords.length} keywords to src/site-keywords.json (anchors + latest ${seoVideos.length} videos).`);
